_PATTERN = re.compile(
    r"\s*(?:([0-9]+)d)?(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?\s*"
)

_MULTIPLIERS = (24 * 60 * 60, 60 * 60, 60, 1)


def parse_duration(s):
    """Parse a duration string such as '1h30m' into seconds.

    Units must appear at most once, in the order d, h, m, s. Surrounding
    whitespace is ignored. Invalid input raises ValueError.
    """
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    match = _PATTERN.fullmatch(s)
    if match is None:
        raise ValueError(f"invalid duration: {s!r}")

    parts = match.groups()
    if all(part is None for part in parts):
        raise ValueError(f"invalid duration: {s!r}")

    return sum(
        int(amount) * multiplier
        for amount, multiplier in zip(parts, _MULTIPLIERS)
        if amount is not None
    )
